-- Isolamento real entre empresas e unidades. Todos os dados são fictícios e revertidos.
begin;create extension if not exists pgtap;select plan(5);
set local role authenticated;select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select is((select count(*) from public.empresas),1::bigint,'usuário vê apenas sua empresa');select is((select nome from public.empresas limit 1),'Empresa Alpha','empresa Beta não vaza');select is((select count(*) from public.unidades),1::bigint,'usuário vê apenas sua unidade');select is((select count(*) from public.auditoria_eventos),0::bigint,'sem permissão não vê auditoria');
select is(public.tem_unidade('b1000000-0000-0000-0000-000000000002'),false,'função nega outra unidade');select * from finish();rollback;
